import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); StringTokenizer st = new StringTokenizer(br.readLine()); int T = Integer.parseInt(st.nextToken()); while (T-- > 0) { st = new StringTokenizer(br.readLine()); int N = Integer.parseInt(st.nextToken()); int Q = Integer.parseInt(st.nextToken()); int[] A = new int[N]; long sumA = 0; st = new StringTokenizer(br.readLine()); for (int i = 0; i < N; i++) { A[i] = Integer.parseInt(st.nextToken()); sumA += A[i]; } while (Q-- > 0) { long X = Long.parseLong(br.readLine()); long target = 2 * sumA - X; boolean found = false; for (int i = 0; i < N && !found; i++) { for (int j = 0; j < N; j++) { if (i == j) continue; if (A[i] + A[j] == target) { found = true; List<Integer> res = new ArrayList<>(); res.add(A[i]); boolean[] used = new boolean[N]; used[i] = true; used[j] = true; for (int k = 0; k < N; k++) { if (!used[k]) { res.add(A[k]); } } res.add(A[j]); StringBuilder sb = new StringBuilder(); for (int k = 0; k < N; k++) { sb.append(res.get(k)).append(k == N - 1 ? "" : " "); } System.out.println(sb.toString()); break; } } } if (!found) { System.out.println("-1"); } } } } }